let currentLang = 'zh';
let currentPage = 'home';
let currentRecipeId = null;
let currentCultureCategory = null;
let currentScenario = null;
let previousPage = null;
let searchQuery = '';
let searchDisplayQuery = '';
let isMobileMenuOpen = false;

function t(key) {
    const keys = key.split('.');
    let value = translations[currentLang];
    for (const k of keys) {
        if (value == null || typeof value !== 'object' || !(k in value)) {
            return key;
        }
        value = value[k];
    }
    return value;
}

function escapeHtml(value) {
    return String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function assetPath(path) {
    if (!path || /^https?:\/\//.test(path) || path.startsWith('data:') || path.startsWith('assets/')) {
        return path;
    }

    const fileName = path.split('/').pop();

    if (/\.(mp4|webm|mov)$/i.test(fileName)) {
        return `assets/videos/${fileName}`;
    }

    if (/\.(png|jpe?g|gif|webp)$/i.test(fileName)) {
        return `assets/images/${fileName}`;
    }

    return path;
}

function normalizeRecipeAssets(recipe) {
    recipe.image = assetPath(recipe.image);
    recipe.video = assetPath(recipe.video);

    if (recipe.culture?.illustration) {
        recipe.culture.illustration = assetPath(recipe.culture.illustration);
    }

    return recipe;
}

recipes.forEach(normalizeRecipeAssets);
communityPosts.forEach(post => {
    post.image = assetPath(post.image);
});

function setLanguage(lang) {
    currentLang = lang;
    document.querySelectorAll('.lang-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.lang === lang);
    });
    render();
}

function navigateTo(page, recipeId = null, cultureCategory = null, scenario = null) {
    previousPage = currentPage;
    currentPage = page;
    currentRecipeId = recipeId;
    currentCultureCategory = cultureCategory;
    currentScenario = scenario;
    isMobileMenuOpen = false;
    render();
    window.scrollTo(0, 0);
}

function toggleMobileMenu() {
    isMobileMenuOpen = !isMobileMenuOpen;
    render();
}

function render() {
    const app = document.getElementById('app');
    
    let content = `
        <header>
            <div class="container">
                <nav>
                    <a href="#" class="logo" onclick="navigateTo('home'); return false;">
                        <span>🥢</span>
                        <span>口袋中餐 / Pocket Chinese</span>
                    </a>
                    <button
                        class="menu-toggle"
                        type="button"
                        onclick="toggleMobileMenu()"
                        aria-label="${currentLang === 'zh' ? '切换导航菜单' : 'Toggle navigation menu'}"
                        aria-expanded="${isMobileMenuOpen}"
                    >
                        ☰
                    </button>
                    <ul class="nav-links ${isMobileMenuOpen ? 'open' : ''}">
                        <li><a href="#" onclick="navigateTo('home'); return false;" class="${currentPage === 'home' ? 'active' : ''}">${t('nav.home')}</a></li>
                        <li><a href="#" onclick="navigateTo('scenarios'); return false;" class="${currentPage === 'scenarios' ? 'active' : ''}">${t('nav.scenarios')}</a></li>
                        <li><a href="#" onclick="navigateTo('recipes', null, null, null); return false;" class="${currentPage === 'recipes' ? 'active' : ''}">${t('nav.recipes')}</a></li>
                        <li><a href="#" onclick="navigateTo('culture'); return false;" class="${currentPage === 'culture' ? 'active' : ''}">${t('nav.culture')}</a></li>
                        <li><a href="#" onclick="navigateTo('community'); return false;" class="${currentPage === 'community' ? 'active' : ''}">${t('nav.community')}</a></li>
                    </ul>
                    <div class="header-right">
                        <div class="search-container">
                            <input type="text" id="search-input" value="${escapeHtml(searchDisplayQuery)}" placeholder="${t('search.placeholder')}" onkeyup="handleSearch(event)">
                            <button onclick="performSearch()">${t('search.button')}</button>
                        </div>
                        <div class="lang-switch">
                            <button class="lang-btn ${currentLang === 'zh' ? 'active' : ''}" data-lang="zh" onclick="setLanguage('zh')">中文</button>
                            <button class="lang-btn ${currentLang === 'en' ? 'active' : ''}" data-lang="en" onclick="setLanguage('en')">EN</button>
                        </div>
                    </div>
                </nav>
            </div>
        </header>
    `;

    if (currentPage === 'home') {
        content += renderHomePage();
    } else if (currentPage === 'scenarios') {
        content += renderScenariosPage();
    } else if (currentPage === 'recipes') {
        content += renderRecipesPage();
    } else if (currentPage === 'recipeDetail') {
        content += renderRecipeDetailPage();
    } else if (currentPage === 'culture') {
        if (currentCultureCategory) {
            content += renderCultureCategoryPage(currentCultureCategory);
        } else {
            content += renderCulturePage();
        }
    } else if (currentPage === 'festivalCategories') {
        content += renderFestivalCategoriesPage();
    } else if (currentPage === 'community') {
        content += renderCommunityPage();
    }

    content += `
        <footer>
            <div class="container">
                <p>${t('footer.text')}</p>
            </div>
        </footer>
    `;

    app.innerHTML = content;
}

