function renderCommunityPost(post) {
    const timeAgo = getTimeAgo(post.timestamp);
    const safeCaption = escapeHtml(post.caption[currentLang]);
    return `
        <div class="community-post">
            <div class="post-header">
                <img src="${post.user.avatar}" alt="${post.user.name}" class="user-avatar">
                <div class="user-info">
                    <h4>${post.user.name}</h4>
                    <span class="post-time">${timeAgo}</span>
                </div>
            </div>
            <img src="${post.image}" alt="Post image" class="post-image" onerror="this.onerror=null; this.src='https://via.placeholder.com/400x300?text=美食图片';">
            <div class="post-content">
                <p class="post-caption">${safeCaption}</p>
                <div class="post-actions">
                    <button class="action-button" onclick="likePost(${post.id})">
                        <span>❤️</span>
                        <span class="action-count">${post.likes}</span>
                    </button>
                    <button class="action-button" onclick="toggleComments(${post.id})">
                        <span>💬</span>
                        <span class="action-count">${post.comments.length}</span>
                    </button>
                    <button class="action-button" onclick="sharePost(${post.id})">
                        <span>📤</span>
                    </button>
                </div>
                <div id="comments-${post.id}" class="comments-section" style="display: none;">
                    <div class="comments-list">
                        ${post.comments.map(comment => `
                            <div class="comment">
                                <span class="comment-user">${comment.user}:</span>
                                <span class="comment-text">${escapeHtml(comment.text[currentLang])}</span>
                            </div>
                        `).join('')}
                    </div>
                    <div class="add-comment">
                        <input type="text" id="comment-input-${post.id}" placeholder="${t('community.comment')}...">
                        <button onclick="addComment(${post.id})">${t('common.send')}</button>
                    </div>
                </div>
            </div>
        </div>
    `;
}

function getTimeAgo(timestamp) {
    const now = new Date();
    const postDate = new Date(timestamp);
    const diffInMs = now - postDate;
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    
    if (diffInDays === 0) {
        const diffInHours = Math.floor(diffInMs / (1000 * 60 * 60));
        if (diffInHours === 0) {
            const diffInMinutes = Math.floor(diffInMs / (1000 * 60));
            if (currentLang === 'zh') {
                return diffInMinutes < 1 ? '刚刚' : `${diffInMinutes}分钟前`;
            }
            return diffInMinutes < 1 ? 'Just now' : `${diffInMinutes} min ago`;
        }
        return currentLang === 'zh' ? `${diffInHours}小时前` : `${diffInHours} hr ago`;
    } else if (diffInDays === 1) {
        return currentLang === 'zh' ? '昨天' : 'Yesterday';
    } else if (diffInDays < 7) {
        return currentLang === 'zh' ? `${diffInDays}天前` : `${diffInDays} days ago`;
    } else {
        return postDate.toLocaleDateString();
    }
}

function openShareModal() {
    document.getElementById('share-modal').style.display = 'block';
}

function closeShareModal() {
    document.getElementById('share-modal').style.display = 'none';
    document.getElementById('share-image').value = '';
    document.getElementById('share-caption').value = '';
    document.getElementById('image-preview').innerHTML = '';
}

function previewImage(event) {
    const file = event.target.files[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = function(e) {
            document.getElementById('image-preview').innerHTML = `<img src="${e.target.result}" alt="Preview">`;
        };
        reader.readAsDataURL(file);
    }
}

function submitPost() {
    const imageInput = document.getElementById('share-image');
    const captionInput = document.getElementById('share-caption');
    
    if (!imageInput.files[0] || !captionInput.value.trim()) {
        alert(t('common.uploadRequired'));
        return;
    }
    
    const reader = new FileReader();
    reader.onload = function(e) {
        const newPost = {
            id: communityPosts.length + 1,
            user: {
                name: '我',
                avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Me'
            },
            image: e.target.result,
            caption: {
                zh: captionInput.value,
                en: captionInput.value
            },
            likes: 0,
            comments: [],
            timestamp: new Date().toISOString()
        };
        
        communityPosts.unshift(newPost);
        closeShareModal();
        render();
    };
    reader.readAsDataURL(imageInput.files[0]);
}

function likePost(postId) {
    const post = communityPosts.find(p => p.id === postId);
    if (post) {
        post.likes++;
        render();
    }
}

function toggleComments(postId) {
    const commentsSection = document.getElementById(`comments-${postId}`);
    if (commentsSection) {
        commentsSection.style.display = commentsSection.style.display === 'none' ? 'block' : 'none';
    }
}

function addComment(postId) {
    const input = document.getElementById(`comment-input-${postId}`);
    const text = input.value.trim();
    
    if (!text) return;
    
    const post = communityPosts.find(p => p.id === postId);
    if (post) {
        post.comments.push({
            user: '我',
            text: {
                zh: text,
                en: text
            }
        });
        render();
    }
}

async function sharePost(postId) {
    const post = communityPosts.find(p => p.id === postId);
    if (post) {
        try {
            if (navigator.share) {
                await navigator.share({
                    title: post.caption[currentLang],
                    text: post.caption[currentLang],
                    url: window.location.href
                });
            } else if (navigator.clipboard?.writeText) {
                await navigator.clipboard.writeText(window.location.href);
                alert(t('common.shareCopied'));
            } else {
                alert(t('common.shareFallback'));
            }
        } catch (error) {
            if (error?.name !== 'AbortError') {
                alert(t('common.shareFallback'));
            }
        }
    }
}

